			return;
		}

	}

	private void configureTableColumns(TableChooserDialog dialog) {

		StringColumnDisplay functionNameColumn = new _Anon_StringColumnDisplay_1();

		ColumnDisplay<Integer> highOpsColumn = new _Anon_AbstractComparableColumnDisplay_2();

		ColumnDisplay<Integer> instructionColumn = new _Anon_AbstractComparableColumnDisplay_3();

		ColumnDisplay<Double> ratioColumn = new _Anon_AbstractComparableColumnDisplay_4();
		dialog.addCustomColumn(functionNameColumn);
		dialog.addCustomColumn(highOpsColumn);
		dialog.addCustomColumn(instructionColumn);
		dialog.addCustomColumn(ratioColumn);
	}


